function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 50000) return 'nums needs 2 to 50000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 50000)) return 'Each value is an integer from 0 to 50000.';
  return null;
}

