function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(2, 10);
    const top = rand() < 0.2 ? 50000 : pick(1, 9);
    const shape = rand();
    const nums = Array.from({ length: n }, () => pick(0, top));
    if (shape < 0.15) nums.sort((a, b) => b - a);
    return [nums];
  }
  const n = pick(1500, 2000);
  const shape = rand();
  if (shape < 0.35) return [Array.from({ length: n }, () => pick(0, 50000))];
  // A mostly falling array keeps the best ramp short and the stack long.
  if (shape < 0.7) return [Array.from({ length: n }, (_, i) => Math.min(50000, Math.max(0, 50000 - i * 25 + pick(-30, 30))))];
  // A noisy rising array, where the widest ramp is long.
  return [Array.from({ length: n }, (_, i) => Math.min(50000, i * 20 + pick(0, 200)))];
}
